SELECT b.bid_notice_id,b.notice_posted_local,b.bid_ntce_name,b.demand_institution_name,b.detailed_product_class_no,b.detailed_product_class_name,COALESCE((SELECT CASE WHEN count(DISTINCT COALESCE(sc.cmpnt_yn,cat.cmpnt_yn))=1 THEN CASE min(COALESCE(sc.cmpnt_yn,cat.cmpnt_yn)) WHEN 'Y' THEN 'part' WHEN 'N' THEN 'product' END WHEN count(DISTINCT COALESCE(sc.cmpnt_yn,cat.cmpnt_yn))>1 THEN 'mixed' END FROM search_classes sc LEFT JOIN catalog_item_category cat ON cat.prdct_idnt_no=sc.product_id WHERE sc.domain='BID' AND sc.source_id=b.bid_notice_id),'unknown'),NULL,NULL,NULL,NULL,NULL,1,0,0,'UNLINKED' FROM bid_notice b WHERE (?1='' OR b.bid_ntce_name LIKE ?2 OR b.demand_institution_name LIKE ?2 OR b.bid_ntce_no LIKE ?2 OR b.detailed_product_class_no LIKE ?2 OR EXISTS(SELECT 1 FROM search_classes sc WHERE sc.domain='BID' AND sc.source_id=b.bid_notice_id AND (sc.classification_no LIKE ?2 OR sc.detailed_no LIKE ?2 OR sc.product_id LIKE ?2 OR sc.classification_name LIKE ?2 OR sc.detailed_name LIKE ?2))) AND (?3='all' OR EXISTS(SELECT 1 FROM search_classes sc LEFT JOIN catalog_item_category cat ON cat.prdct_idnt_no=sc.product_id WHERE sc.domain='BID' AND sc.source_id=b.bid_notice_id AND CASE COALESCE(sc.cmpnt_yn,cat.cmpnt_yn) WHEN 'Y' THEN 'part' WHEN 'N' THEN 'product' END=?3)) ORDER BY b.notice_posted_local DESC,b.bid_notice_id DESC LIMIT ?4